create or replace function private.flag_free_vote_velocity() returns trigger language plpgsql security definer set search_path='' as $$ declare e public.events; recent_count integer; begin if new.payment_attempt_id is not null or new.voter_user_id is null then return new; end if; select * into e from public.events where id=new.event_id; select coalesce(sum(quantity),0)::integer into recent_count from public.vote_batches where voter_user_id=new.voter_user_id and event_id=new.event_id and created_at>now()-interval '1 hour'; if recent_count>=25 then insert into public.moderation_flags(organization_id,event_id,user_id,kind,severity,details) values(e.organization_id,e.id,new.voter_user_id,'free_vote_velocity',least(5,1+(recent_count/25)), 'Verified voter cast '||recent_count||' free votes in the last hour.'); end if; return new; end $$;
drop trigger if exists free_vote_velocity_flag on public.vote_batches;
create trigger free_vote_velocity_flag after insert on public.vote_batches for each row execute function private.flag_free_vote_velocity();
